bool carPooling(vector<vector<int>>& trips, int capacity) {
    vector<pair<int, int>> events;
    for (auto& t : trips) {
        events.push_back({t[1], t[0]});
        events.push_back({t[2], -t[0]});
    }
    sort(events.begin(), events.end());
    int curr = 0;
    for (auto& e : events) {
        curr += e.second;
        if (curr > capacity) return false;
    }
    return true;
}

import java.util.*;
public class Solution {
    public boolean carPooling(int[][] trips, int capacity) {
        List<int[]> events = new ArrayList<>();
        for (int[] t : trips) {
            events.add(new int[]{t[1], t[0]});
            events.add(new int[]{t[2], -t[0]});
        }
        events.sort((a, b) -> a[0] != b[0] ? Integer.compare(a[0], b[0]) : Integer.compare(a[1], b[1]));
        int curr = 0;
        for (int[] e : events) {
            curr += e[1];
            if (curr > capacity) return false;
        }
        return true;
    }
}

function carPooling(trips, capacity) {
  const events = [];
  for (const [num, start, end] of trips) {
    events.push([start, num]);
    events.push([end, -num]);
  }
  events.sort((a, b) => a[0] !== b[0] ? a[0] - b[0] : a[1] - b[1]);
  let curr = 0;
  for (const [time, num] of events) {
    curr += num;
    if (curr > capacity) return false;
